/**
 * Structured Logger — Centralized logging with pino
 * 
 * Replaces unstructured console.log/warn/error across the server.
 * Features:
 * - JSON structured output in production, pretty-print in development
 * - Request correlation IDs
 * - PII redaction
 * - Domain-specific child loggers
 * - Sentry integration for error-level logs
 * 
 * GravitoLogger type: wraps pino.Logger with a flexible LogMethod that
 * accepts both (string, object) and (object, string) call patterns.
 * This eliminates 387+ TS2769 errors from pino v10's strict generics.
 */
import pino from 'pino';

// ============================================================================
// FLEXIBLE LOG METHOD TYPE
// ============================================================================

/**
 * A flexible log method that accepts both pino patterns:
 *   logger.info("message", { data })   — used throughout codebase
 *   logger.info({ data }, "message")   — pino's canonical form
 *   logger.info("message")             — simple string
 *   logger.info({ data })              — object only
 */
interface FlexibleLogMethod {
  (msg: string, ...args: any[]): void;
  (obj: object, msg?: string, ...args: any[]): void;
  (...args: any[]): void;
}

/**
 * GravitoLogger — pino.Logger with relaxed method signatures.
 * All log methods accept any argument order that pino supports at runtime.
 */
export type GravitoLogger = {
  trace: FlexibleLogMethod;
  debug: FlexibleLogMethod;
  info: FlexibleLogMethod;
  warn: FlexibleLogMethod;
  error: FlexibleLogMethod;
  fatal: FlexibleLogMethod;
  child(bindings: Record<string, unknown>, options?: pino.ChildLoggerOptions): GravitoLogger;
  level: string;
  isLevelEnabled(level: string): boolean;
  silent: FlexibleLogMethod;
};

// ============================================================================
// PII REDACTION — Delegates to centralized sanitizer (server/_core/pii/sanitize.ts)
// Falls back to inline patterns if the module is not available.
// ============================================================================
let _sanitizeObject: ((obj: unknown) => unknown) | null = null;
try {
  const pii = require('./pii/sanitize');
  _sanitizeObject = pii.sanitizeObject;
} catch { /* centralized PII module not available — use fallback */ }

// Fallback patterns (kept for resilience if centralized module fails to load)
const PII_PATTERNS_FALLBACK: Array<{ pattern: RegExp; replacement: string }> = [
  { pattern: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, replacement: '[REDACTED_EMAIL]' },
  { pattern: /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b/g, replacement: '[REDACTED_PAN]' },
  { pattern: /\bsk[-_](?:test|live|ant)[-_][A-Za-z0-9_-]{20,}\b/g, replacement: '[REDACTED_SECRET]' },
  { pattern: /\bwhsec_[A-Za-z0-9_-]{20,}\b/g, replacement: '[REDACTED_SECRET]' },
  { pattern: /\beyJhbGciOi[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, replacement: '[REDACTED_JWT]' },
  { pattern: /password["']?\s*[:=]\s*["']?[^\s"',}]+/gi, replacement: 'password=[REDACTED_SECRET]' },
];

function redactPII(obj: unknown): unknown {
  // Use centralized sanitizer if available
  if (_sanitizeObject) {
    try {
      return _sanitizeObject(obj);
    } catch { /* fall through to inline fallback */ }
  }

  // Inline fallback
  if (typeof obj === 'string') {
    let result = obj;
    for (const { pattern, replacement } of PII_PATTERNS_FALLBACK) {
      result = result.replace(pattern, replacement);
    }
    return result;
  }
  if (Array.isArray(obj)) {
    return obj.map(redactPII);
  }
  if (obj && typeof obj === 'object') {
    const redacted: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj)) {
      if (/password|secret|token|apikey|api_key|authorization|cookie|ssn|credit_card/i.test(key)) {
        redacted[key] = '[REDACTED_SECRET]';
      } else {
        redacted[key] = redactPII(value);
      }
    }
    return redacted;
  }
  return obj;
}

// ============================================================================
// LOGGER CONFIGURATION
// ============================================================================
const isDev = process.env.NODE_ENV !== 'production';

const baseLogger: GravitoLogger = pino({
  level: process.env.LOG_LEVEL || (isDev ? 'debug' : 'info'),
  transport: isDev
    ? {
        target: 'pino-pretty',
        options: {
          colorize: true,
          translateTime: 'SYS:yyyy-mm-dd HH:MM:ss.l',
          ignore: 'pid,hostname',
        },
      }
    : undefined,
  formatters: {
    level(label) {
      return { level: label };
    },
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  // Redact sensitive fields at the serializer level
  serializers: {
    req: (req) => ({
      method: req.method,
      url: req.url,
      remoteAddress: req.remoteAddress,
    }),
    res: (res) => ({
      statusCode: res.statusCode,
    }),
    err: pino.stdSerializers.err,
  },
}) as unknown as GravitoLogger;

// ============================================================================
// CORRELATION ID MANAGEMENT
// ============================================================================
let correlationCounter = 0;

export function generateCorrelationId(): string {
  correlationCounter += 1;
  const timestamp = Date.now().toString(36);
  const counter = correlationCounter.toString(36).padStart(4, '0');
  const random = Math.random().toString(36).substring(2, 6);
  return `${timestamp}-${counter}-${random}`;
}

// ============================================================================
// DOMAIN-SPECIFIC CHILD LOGGERS
// ============================================================================
export type LogDomain =
  | 'webhook'
  | 'auth'
  | 'governance'
  | 'stripe'
  | 'scheduler'
  | 'api'
  | 'nervous-system'
  | 'team'
  | 'usage'
  | 'resolver'
  | 'security'
  | 'database'
  | 'llm'
  | 'email'
  | 'storage'
  | 'mcp'
  | 'general'
  | 'degraded-policy-engine'
  | 'direct-dispatch'
  | 'fail-closed-gate'
  | 'governance-coverage'
  | 'mcp-health'
  | 'mcp-reliability'
  | 'product-context'
  | 'product-onboarding'
  | 'prometheus-metrics'
  | 'safe-llm'
  | 'authority-alerting'
  | 'backfill-audit-processor'
  | 'chaos-test-framework'
  | 'circuit-breaker-alerts'
  | 'composite-confidence-scorer'
  | 'config-admin-api'
  | 'config-db-adapter'
  | 'config-drizzle-adapter'
  | 'curiosity-engine'
  | 'curiosity-integration'
  | 'curiosity-shadow-mode'
  | 'db-config-manager'
  | 'deterministic-fallback'
  | 'dynamic-sampling-controller'
  | 'enterprise'
  | 'error-contracts'
  | 'governance-hooks'
  | 'governance-signal-normalizer'
  | 'governance-summary'
  | 'gravito-authority-layer'
  | 'gravito-enterprise-hardening'
  | 'integrated-nervous-system'
  | 'internal-rate-limiter'
  | 'invariant-monitor'
  | 'load-test-harness'
  | 'mcp-audit'
  | 'mcp-governance-health'
  | 'mcp-rate-limiter'
  | 'mcp-sync-wrapper'
  | 'observation-baseline'
  | 'opportunistic-semantic-layer'
  | 'ordinal-context-guard'
  | 'production-audit'
  | 'production-budget'
  | 'promotion-alerting'
  | 'promotion-controller'
  | 'promotion-readiness-gate'
  | 'billing'
  | 'emotional-geometry'
  | 'alert-sse'
  | 'neurocosmology-advanced'
  | 'tenant-analytics'
  | 'tenant-governance'
  | 'governance-badge'
  | 'ts-code-scanner'
  | 'stability:coherence-modeling'
  | 'stability:drift-vector'
  | 'stability:pressure-modeling'
  | 'stability:identity-continuity'
  | 'stability:stability-index'
  | 'stability:behavioral-audit-ledger'
  | 'containment:autonomy-boundary-fsm'
  | 'containment:reliability-envelope'
  | 'containment:escalation-protocol'
  | 'containment:resource-limiter'
  | 'containment:output-sanitizer'
  | 'containment:temporal-containment'
  | 'containment:interaction-firewall'
  | 'containment:orchestrator'
  | 'dsor:agent-middleware'
  | 'dsor:integration'
  | 'dsor:telemetry-bridge'
  | 'dsor:retention-persistence'
  | 'dsor:websocket'
  | 'control-plane'
  | 'control-plane:autonomy'
  | 'control-plane:reliability'
  | 'control-plane:adversarial'
  | 'control-plane:drift'
  | 'control-plane:ledger'
  | 'control-plane:killswitch'
  | 'control-plane:gri'
  | 'control-plane:enforcement'
  | 'control-plane:permissions'
  | 'control-plane:budgets'
  | 'control-plane:portfolio'
  | 'control-plane:observability'
  | 'control-plane:certificates'
  | 'control-plane:policy'
  | 'control-plane:coordination'
  | 'control-plane:devworkflow'
  | 'control-plane:identity'
  | 'control-plane:selfgov'
  | 'control-plane:redline'
  | 'control-plane:persistence'
  | 'enhanced-tools'
  | 'neurocosmology-mechanistic'
  | 'scheduler-tuner'
  | 'anomaly-test-gen'
  | 'inference-gateway'
  | 'voice-stream-gateway';

/**
 * Create a domain-specific child logger.
 * Usage:
 *   const log = createLogger('webhook');
 *   log.info({ eventId: 'evt_123' }, 'Processing webhook event');
 *   log.error({ err }, 'Webhook processing failed');
 *   log.info('Simple message');
 *   log.warn('Message with data', { key: 'value' });
 */
export function createLogger(domain: LogDomain, context?: Record<string, unknown>): GravitoLogger {
  return baseLogger.child({
    domain,
    ...context,
  });
}

/**
 * Create a request-scoped logger with correlation ID.
 * Usage in Express middleware:
 *   const log = createRequestLogger('api', req);
 *   log.info('Processing request');
 */
export function createRequestLogger(domain: LogDomain, req?: { headers?: Record<string, string | string[] | undefined> }): GravitoLogger {
  const correlationId = (req?.headers?.['x-correlation-id'] as string) || generateCorrelationId();
  return baseLogger.child({
    domain,
    correlationId,
  });
}

/**
 * Safe log helper that redacts PII from data before logging.
 * Use for any data that might contain user information.
 */
export function safeLog(logger: GravitoLogger, level: 'info' | 'warn' | 'error' | 'debug', data: Record<string, unknown>, message: string) {
  const redacted = redactPII(data) as Record<string, unknown>;
  logger[level](redacted, message);
}

// ============================================================================
// EXPRESS MIDDLEWARE
// ============================================================================
/**
 * Express middleware that adds a correlation ID to every request
 * and logs request/response pairs.
 */
export function requestLoggingMiddleware() {
  const httpLogger = createLogger('api');

  return (req: any, res: any, next: any) => {
    const correlationId = (req.headers['x-correlation-id'] as string) || generateCorrelationId();
    req.correlationId = correlationId;
    res.setHeader('x-correlation-id', correlationId);

    const startTime = Date.now();

    // Log on response finish
    res.on('finish', () => {
      const duration = Date.now() - startTime;
      const logData = {
        correlationId,
        method: req.method,
        url: req.originalUrl || req.url,
        statusCode: res.statusCode,
        duration,
        userAgent: req.headers['user-agent'],
      };

      if (res.statusCode >= 500) {
        httpLogger.error(logData, 'Request failed');
      } else if (res.statusCode >= 400) {
        httpLogger.warn(logData, 'Request client error');
      } else if (duration > 5000) {
        httpLogger.warn(logData, 'Slow request');
      } else {
        // Only log non-health-check requests at info level
        if (!req.url?.includes('/health') && !req.url?.includes('/favicon')) {
          httpLogger.debug(logData, 'Request completed');
        }
      }
    });

    next();
  };
}

// ============================================================================
// PRE-BUILT DOMAIN LOGGERS (convenience exports)
// ============================================================================
export const webhookLog = createLogger('webhook');
export const authLog = createLogger('auth');
export const governanceLog = createLogger('governance');
export const stripeLog = createLogger('stripe');
export const schedulerLog = createLogger('scheduler');
export const apiLog = createLogger('api');
export const teamLog = createLogger('team');
export const usageLog = createLogger('usage');
export const resolverLog = createLogger('resolver');
export const securityLog = createLogger('security');
export const dbLog = createLogger('database');
export const llmLog = createLogger('llm');
export const emailLog = createLogger('email');
export const storageLog = createLogger('storage');
export const generalLog = createLogger('general');

// Default export is the base logger
export default baseLogger;

