275	function hashApiKey(key: string): string {
276	  return createHash('sha256').update(key).digest('hex');
277	}
278	
279	export function generateApiKey(): { key: string; hash: string; prefix: string } {
280	  const key = `grav_${randomBytes(32).toString('hex')}`;
281	  const hash = hashApiKey(key);
282	  // Prod `api_keys.key_prefix` is varchar(12) NOT NULL — a 16-char prefix
283	  // overflows it (Postgres 22001) and silently fails key creation/regeneration.
284	  const prefix = key.substring(0, 12);
285	  return { key, hash, prefix };
286	}
