547	// ============ Rate Limiting Functions (Database-backed) ============
548	
549	export async function checkRateLimit(userId: number, plan: string): Promise<{
550	  allowed: boolean;
551	  remaining: number;
552	  resetAt: number;
553	  limit: number;
554	}> {
555	  const db = await getDb();
556	  const limits = getPlanLimit(plan);
557	  const now = Date.now();
558	  const windowMs = 60 * 1000; // 1 minute window
559	  const windowKey = `${userId}-${Math.floor(now / windowMs)}`;
560	  
561	  if (!db) {
562	    // Fallback: allow request if DB unavailable (fail open for availability)
563	    dbLog.warn({}, '[RateLimit] Database unavailable, allowing request');
564	    return { allowed: true, remaining: limits.rate, resetAt: now + windowMs, limit: limits.rate };
565	  }
566	
567	  try {
568	    // Check for existing window
569	    const existing = await db.select()
570	      .from(rateLimits)
571	      .where(and(
572	        eq(rateLimits.userId, userId),
573	        eq(rateLimits.windowKey, windowKey)
574	      ))
575	      .limit(1);
576	
577	    if (existing.length > 0) {
578	      const record = existing[0];
579	      
580	      if (record.requestCount >= limits.rate) {
581	        return {
582	          allowed: false,
583	          remaining: 0,
584	          resetAt: record.windowEnd,
585	          limit: limits.rate
586	        };
587	      }
588	
589	      // Increment count
590	      await db.update(rateLimits)
591	        .set({ requestCount: sql`${rateLimits.requestCount} + 1` })
592	        .where(eq(rateLimits.id, record.id));
593	
594	      return {
595	        allowed: true,
596	        remaining: limits.rate - record.requestCount - 1,
597	        resetAt: record.windowEnd,
598	        limit: limits.rate
599	      };
600	    }
601	
602	    // Create new window
603	    const windowEnd = now + windowMs;
604	    await db.insert(rateLimits).values({
605	      userId,
606	      windowKey,
607	      requestCount: 1,
608	      windowStart: now,
609	      windowEnd,
610	    });
611	
612	    return {
613	      allowed: true,
614	      remaining: limits.rate - 1,
615	      resetAt: windowEnd,
616	      limit: limits.rate
617	    };
618	  } catch (error) {
619	    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[RateLimit] Error checking rate limit');
620	    // Fail open for availability
621	    return { allowed: true, remaining: limits.rate, resetAt: now + windowMs, limit: limits.rate };
622	  }
623	}
