801	/**
802	 * Calculate lead score based on scan results
803	 * Higher escalation risk + higher value at risk = higher score
804	 */
805	function calculateLeadScore(data: {
806	  escalationRisk?: number;
807	  churnProbability?: number;
808	  valueAtRisk?: number;
809	}): { score: number; tier: 'cold' | 'warm' | 'hot' | 'qualified' } {
810	  let score = 0;
811	  
812	  // Escalation risk contributes 0-40 points
813	  if (data.escalationRisk) {
814	    score += Math.round(data.escalationRisk * 0.4);
815	  }
816	  
817	  // Churn probability contributes 0-30 points
818	  if (data.churnProbability) {
819	    score += Math.round(data.churnProbability * 0.3);
820	  }
821	  
822	  // Value at risk contributes 0-30 points (capped at $10k)
823	  if (data.valueAtRisk) {
824	    const valueScore = Math.min(data.valueAtRisk / 10000, 1) * 30;
825	    score += Math.round(valueScore);
826	  }
827	  
828	  // Determine tier based on score
829	  let tier: 'cold' | 'warm' | 'hot' | 'qualified';
830	  if (score >= 70) {
831	    tier = 'qualified';
832	  } else if (score >= 50) {
833	    tier = 'hot';
834	  } else if (score >= 30) {
835	    tier = 'warm';
836	  } else {
837	    tier = 'cold';
838	  }
839	  
840	  return { score, tier };
841	}
