1051	    return { total: 0, byStatus: {}, byTier: {}, avgScore: 0, todayCount: 0 };
1052	  }
1053	
1054	  try {
1055	    // Total count
1056	    const totalResult = await db.select({ count: sql<number>`COUNT(*)` }).from(leads);
1057	    const total = totalResult[0]?.count || 0;
1058	
1059	    // By status
1060	    const statusResult = await db.select({
1061	      status: leads.status,
1062	      count: sql<number>`COUNT(*)`
1063	    }).from(leads).groupBy(leads.status);
1064	    const byStatus: Record<string, number> = {};
1065	    statusResult.forEach(r => { byStatus[r.status] = r.count; });
1066	
1067	    // By tier
1068	    const tierResult = await db.select({
1069	      tier: leads.leadTier,
1070	      count: sql<number>`COUNT(*)`
1071	    }).from(leads).groupBy(leads.leadTier);
1072	    const byTier: Record<string, number> = {};
1073	    tierResult.forEach(r => { if (r.tier) byTier[r.tier] = r.count; });
1074	
1075	    // Average score
1076	    const avgResult = await db.select({
1077	      avg: sql<number>`AVG(${leads.leadScore})`
1078	    }).from(leads);
1079	    const avgScore = Math.round(avgResult[0]?.avg || 0);
1080	
1081	    // Today's count
1082	    const today = new Date();
1083	    today.setHours(0, 0, 0, 0);
1084	    const todayResult = await db.select({ count: sql<number>`COUNT(*)` })
1085	      .from(leads)
1086	      .where(sql`${leads.createdAt} >= ${today}`);
1087	    const todayCount = todayResult[0]?.count || 0;
1088	
1089	    return { total, byStatus, byTier, avgScore, todayCount };
1090	  } catch (error) {
