1142	export async function getFeedbackStats(): Promise<{
1143	  total: number;
1144	  correct: number;
1145	  incorrect: number;
1146	  accuracy: number;
1147	  byState: Record<string, { correct: number; incorrect: number }>;
1148	  commonCorrections: Array<{ from: string; to: string; count: number }>;
1149	}> {
1150	  const db = await getDb();
1151	  if (!db) {
1152	    return { total: 0, correct: 0, incorrect: 0, accuracy: 0, byState: {}, commonCorrections: [] };
1153	  }
1154	
1155	  try {
1156	    // Total counts
1157	    const totalResult = await db.select({ count: sql<number>`COUNT(*)` }).from(benefitStateFeedback);
1158	    const total = totalResult[0]?.count || 0;
1159	
1160	    const correctResult = await db.select({ count: sql<number>`COUNT(*)` })
1161	      .from(benefitStateFeedback)
1162	      .where(eq(benefitStateFeedback.isCorrect, true));
1163	    const correct = correctResult[0]?.count || 0;
1164	
1165	    const incorrect = total - correct;
1166	    const accuracy = total > 0 ? Math.round((correct / total) * 100) : 0;
1167	
1168	    // By predicted state
1169	    const byStateResult = await db.select({
1170	      state: benefitStateFeedback.predictedState,
1171	      isCorrect: benefitStateFeedback.isCorrect,
1172	      count: sql<number>`COUNT(*)`
1173	    })
1174	      .from(benefitStateFeedback)
1175	      .groupBy(benefitStateFeedback.predictedState, benefitStateFeedback.isCorrect);
1176	
1177	    const byState: Record<string, { correct: number; incorrect: number }> = {};
1178	    byStateResult.forEach(r => {
1179	      if (!byState[r.state]) {
1180	        byState[r.state] = { correct: 0, incorrect: 0 };
1181	      }
1182	      if (r.isCorrect) {
1183	        byState[r.state].correct = r.count;
1184	      } else {
1185	        byState[r.state].incorrect = r.count;
1186	      }
1187	    });
1188	
1189	    // Common corrections (from -> to)
1190	    const correctionsResult = await db.select({
1191	      from: benefitStateFeedback.predictedState,
1192	      to: benefitStateFeedback.correctedState,
1193	      count: sql<number>`COUNT(*)`
1194	    })
1195	      .from(benefitStateFeedback)
1196	      .where(eq(benefitStateFeedback.isCorrect, false))
1197	      .groupBy(benefitStateFeedback.predictedState, benefitStateFeedback.correctedState)
1198	      .orderBy(sql`COUNT(*) DESC`)
1199	      .limit(10);
1200	
1201	    const commonCorrections = correctionsResult
1202	      .filter(r => r.to)
1203	      .map(r => ({ from: r.from, to: r.to!, count: r.count }));
1204	
1205	    return { total, correct, incorrect, accuracy, byState, commonCorrections };
1206	  } catch (error) {
1207	    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[BenefitStateFeedback] Error getting stats');
1208	    return { total: 0, correct: 0, incorrect: 0, accuracy: 0, byState: {}, commonCorrections: [] };
1209	  }
1210	}
