1463	// ============ Failure Mode Functions (Top Failure Modes Report) ============
1464	
1465	export async function recordFailureMode(
1466	  predictedState: string,
1467	  actualState: string,
1468	  signals?: string[],
1469	  reason?: string
1470	): Promise<void> {
1471	  const db = await getDb();
1472	  if (!db) return;
1473	
1474	  const confusionPair = `${predictedState}->${actualState}`;
1475	
1476	  try {
1477	    // Check if this confusion pair exists
1478	    const existing = await db.select()
1479	      .from(failureModes)
1480	      .where(eq(failureModes.confusionPair, confusionPair))
1481	      .limit(1);
1482	
1483	    if (existing.length > 0) {
1484	      // Update existing
1485	      const existingSignals = existing[0].commonSignals 
1486	        ? JSON.parse(existing[0].commonSignals) as string[]
1487	        : [];
1488	      const existingReasons = existing[0].commonReasons
1489	        ? JSON.parse(existing[0].commonReasons) as string[]
1490	        : [];
1491	
1492	      // Merge signals and reasons
1493	      const mergedSignals = [...new Set([...existingSignals, ...(signals || [])])].slice(0, 10);
1494	      const mergedReasons = reason 
1495	        ? [...new Set([...existingReasons, reason])].slice(0, 10)
