/* eslint-disable @typescript-eslint/no-unused-vars, require-await, @typescript-eslint/no-explicit-any, no-return-await -- Legacy DB module carries pre-existing lint debt; this packet only changes connection construction for pooler readiness. */
import { eq, and, sql, desc, like, gte } from "drizzle-orm";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { dbLog } from './_core/logger';
import { 
  InsertUser, 
