  FailureMode,
  InsertFailureMode,
  GravitoReview,
  InsertGravitoReview,
  GravitoUsageStat,
  InsertGravitoUsageStat,
  Pilot,
  InsertPilot,
  PilotProofBlock,
  InsertPilotProofBlock,
  PilotWeeklyReport,
  InsertPilotWeeklyReport,
  PilotExperiment,
  InsertPilotExperiment,
  governanceSettings,
  GovernanceSettings,
  InsertGovernanceSettings,
  governanceAuditLog,
  GovernanceAuditLog,
  InsertGovernanceAuditLog,
  mcpUsageLog,
  McpUsageLog,
  entitlementDenials,
  productEntitlements,
  demoRequests,
  DemoRequest,
  InsertDemoRequest,
  pilotRequests,
  PilotRequest,
  InsertPilotRequest,
  evalTelemetry,
  EvalTelemetryEntry,
  InsertEvalTelemetryEntry,
  remediationRuns,
  RemediationRun,
  InsertRemediationRun,
  governedSurfaces,
  GovernedSurface,
  InsertGovernedSurface,
  governanceAuthorityAudit,
  InsertGovernanceAuthorityAuditRow,
} from "../drizzle/schema";
import { ENV } from './_core/env';
import { buildPostgresOptions } from './_core/postgres-options';
import { createHash, randomBytes } from "crypto";
import { unsafeCast } from '../shared/type-bridge';

let _db: ReturnType<typeof drizzle> | null = null;
/** In-flight initialization promise used to prevent thundering-herd reconnection storms. */
let _initPromise: Promise<ReturnType<typeof drizzle>> | null = null;

/** Thrown when the database is configured but unavailable or connection failed. */
export class DatabaseUnavailableError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DatabaseUnavailableError';
  }
}

async function createDbConnection(): Promise<ReturnType<typeof drizzle>> {
  if (!ENV.databaseUrl) {
    dbLog.fatal('Missing required env var: DATABASE_URL');
    _db = null;
    _initPromise = null;
    throw new DatabaseUnavailableError('Database configuration is missing or invalid');
  }
  try {
    const client = postgres(
      ENV.databaseUrl,
      buildPostgresOptions({
        databaseUrl: ENV.databaseUrl,
        defaultMax: 5,             // Max connections per machine (2 machines × 5 = 10 total)
        idleTimeout: 30,           // Close idle connections after 30s
        connectTimeout: 10,        // Fail fast if can't connect in 10s
        maxLifetime: 60 * 30,      // Recycle connections every 30 minutes
      }),
    );
    const db = drizzle(client);
    _db = db;
    return db;
  } catch (error) {
    _db = null;
    _initPromise = null;
    const err = error instanceof Error ? error : new Error(String(error));
    // Sanitize error message to prevent DATABASE_URL credentials from leaking into logs.
    // Covers standard URL credential patterns: scheme://user:pass@host and scheme://:pass@host
    const sanitizedMessage = err.message
      .replace(/:\/\/([^:@\/]*):([^@\/]+)@/g, '://[REDACTED]:[REDACTED]@')
      .replace(/:\/\/([^@\/]+)@/g, '://[REDACTED]@');
    const sanitizedErr = Object.assign(new Error(sanitizedMessage), { name: err.name });
    dbLog.error({ err: sanitizedErr }, '[Database] Failed to connect to DATABASE_URL — connection error, not a missing config');
    // Re-throw a structured error so callers can distinguish a misconfigured/failed
    // connection from a deliberately unconfigured database (no DATABASE_URL).
    // Do NOT include err.message in the thrown error to avoid leaking connection details.
    throw new DatabaseUnavailableError('Database connection failed');
  }
}

export async function getDb() {
  if (_db) return _db;
  if (!ENV.databaseUrl) return null;
  // Serialize concurrent initialization attempts to avoid thundering herd.
  if (!_initPromise) {
    _initPromise = createDbConnection().finally(() => {
      _initPromise = null;
    });
  }
  return _initPromise;
}

/** End postgres-js pool (Drizzle stores client on `$client`). Safe to call once at shutdown. */
export async function closeDatabaseConnection(): Promise<void> {
  if (!_db) return;
  try {
    const client = (_db as { $client?: { end: (opts?: { timeout?: number }) => Promise<void> } }).$client;
    if (client?.end) {
      await client.end({ timeout: 5000 });
    }
  } finally {
    _db = null;
    _initPromise = null;
  }
}

/** Drizzle transaction handle type — use as parameter type in withTransaction callbacks */
export type DbTransaction = Parameters<Parameters<Exclude<Awaited<ReturnType<typeof getDb>>, null>['transaction']>[0]>[0];

/**
 * Execute a callback within a database transaction.
 * If the callback throws, the transaction is rolled back automatically.
 * Uses Drizzle's built-in transaction support.
 */
export async function withTransaction<T>(fn: (tx: DbTransaction) => Promise<T>): Promise<T> {
  const db = await getDb();
  if (!db) {
    throw new DatabaseUnavailableError('Database unavailable: cannot start transaction');
  }
  return db.transaction(fn);
}

// ============ User Functions ============

export async function upsertUser(user: InsertUser): Promise<void> {
  if (!user.openId) {
    throw new Error("User openId is required for upsert");
  }

  const db = await getDb();
  if (!db) {
    dbLog.error({}, '[Database] Cannot upsert user: database not available');
    throw new Error('Database unavailable: cannot upsert user');
  }

  try {
    const values: InsertUser = {
      openId: user.openId,
    };
    const updateSet: Record<string, unknown> = {};

    const textFields = ["name", "email", "loginMethod", "passwordHash"] as const;
    type TextField = (typeof textFields)[number];

    const assignNullable = (field: TextField) => {
      const value = user[field];
      if (value === undefined) return;
      const normalized = value ?? null;
      values[field] = normalized;
      updateSet[field] = normalized;
    };

    textFields.forEach(assignNullable);

    if (user.lastSignedIn !== undefined) {
      values.lastSignedIn = user.lastSignedIn;
      updateSet.lastSignedIn = user.lastSignedIn;
    }
    if (user.role !== undefined) {
      values.role = user.role;
      updateSet.role = user.role;
    } else if (user.openId === ENV.ownerOpenId) {
      values.role = 'admin';
      updateSet.role = 'admin';
    }

    if (!values.lastSignedIn) {
      values.lastSignedIn = new Date();
    }

    if (Object.keys(updateSet).length === 0) {
      updateSet.lastSignedIn = new Date();
    }

    await db.insert(users).values(values).onConflictDoUpdate({
      target: users.openId,
      set: updateSet,
    });
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Database] Failed to upsert user');
    throw error;
  }
}

export async function getUserByOpenId(openId: string) {
  const db = await getDb();
  if (!db) {
    dbLog.warn({}, '[Database] Cannot get user: database not available');
    return undefined;
  }

  const result = await db.select().from(users).where(eq(users.openId, openId)).limit(1);
  return result.length > 0 ? result[0] : undefined;
}

export async function getUserById(id: number) {
  const db = await getDb();
  if (!db) return undefined;
  const result = await db.select().from(users).where(eq(users.id, id)).limit(1);
  return result.length > 0 ? result[0] : undefined;
}

export async function getUserByEmail(email: string) {
  const db = await getDb();
  if (!db) return undefined;
  const result = await db.select().from(users).where(eq(users.email, email)).limit(1);
  return result.length > 0 ? result[0] : undefined;
}

// ============ API Key Functions ============

function hashApiKey(key: string): string {
  return createHash('sha256').update(key).digest('hex');
}

export function generateApiKey(): { key: string; hash: string; prefix: string } {
  const key = `grav_${randomBytes(32).toString('hex')}`;
  const hash = hashApiKey(key);
  // Prod `api_keys.key_prefix` is varchar(12) NOT NULL — a 16-char prefix
  // overflows it (Postgres 22001) and silently fails key creation/regeneration.
  const prefix = key.substring(0, 12);
  return { key, hash, prefix };
}

export async function createApiKey(userId: number, name?: string) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");

  const { key, hash, prefix } = generateApiKey();

  await db.insert(apiKeys).values({
    userId,
    keyHash: hash,
    keyPrefix: prefix,
    name: name || "Default Key",
    isActive: true,
  });

  return { key, prefix };
}

export async function getApiKeysByUserId(userId: number) {
  const db = await getDb();
  if (!db) return [];

  return db.select({
    id: apiKeys.id,
    keyPrefix: apiKeys.keyPrefix,
    name: apiKeys.name,
    isActive: apiKeys.isActive,
    lastUsedAt: apiKeys.lastUsedAt,
    createdAt: apiKeys.createdAt,
  }).from(apiKeys).where(eq(apiKeys.userId, userId));
}

export async function validateApiKey(key: string) {
  const db = await getDb();
  if (!db) return null;

  const hash = hashApiKey(key);
  const result = await db.select()
    .from(apiKeys)
    .where(and(eq(apiKeys.keyHash, hash), eq(apiKeys.isActive, true)))
    .limit(1);

  if (result.length === 0) return null;

  // Update last used
  await db.update(apiKeys)
    .set({ lastUsedAt: new Date() })
    .where(eq(apiKeys.id, result[0].id));

  return result[0];
}

export async function deleteApiKey(userId: number, keyId: number) {
  const db = await getDb();
  if (!db) return false;

  await db.delete(apiKeys)
    .where(and(eq(apiKeys.id, keyId), eq(apiKeys.userId, userId)));
  return true;
}

export async function regenerateApiKey(userId: number, keyId: number) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");

  const { key, hash, prefix } = generateApiKey();

  await db.update(apiKeys)
    .set({ keyHash: hash, keyPrefix: prefix })
    .where(and(eq(apiKeys.id, keyId), eq(apiKeys.userId, userId)));

  return { key, prefix };
}

// ============ Subscription Functions ============

export async function getSubscriptionByUserId(userId: number) {
  const db = await getDb();
  if (!db) return null;

  const result = await db.select()
    .from(subscriptions)
    .where(eq(subscriptions.userId, userId))
    .limit(1);

  return result.length > 0 ? result[0] : null;
}

export async function createOrUpdateSubscription(data: InsertSubscription) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");

  await db.insert(subscriptions).values(data).onConflictDoUpdate({
    target: subscriptions.userId,
    set: {
      plan: data.plan,
      stripeCustomerId: data.stripeCustomerId,
      stripeSubscriptionId: data.stripeSubscriptionId,
      status: data.status,
      currentPeriodStart: data.currentPeriodStart,
      currentPeriodEnd: data.currentPeriodEnd,
      cancelAtPeriodEnd: data.cancelAtPeriodEnd,
    },
  });
}

export async function updateSubscriptionByStripeId(stripeSubscriptionId: string, data: Partial<InsertSubscription>) {
  const db = await getDb();
  if (!db) return;

  await db.update(subscriptions)
    .set(data)
    .where(eq(subscriptions.stripeSubscriptionId, stripeSubscriptionId));
}

// ============ Usage Functions ============

export async function recordApiUsage(userId: number, apiKeyId: number | null, endpoint: string) {
  const db = await getDb();
  if (!db) return;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Try to increment existing record for today
  const existing = await db.select()
    .from(apiUsage)
    .where(and(
      eq(apiUsage.userId, userId),
      eq(apiUsage.endpoint, endpoint),
      sql`DATE(${apiUsage.date}) = DATE(${today})`
    ))
    .limit(1);

  if (existing.length > 0) {
    await db.update(apiUsage)
      .set({ callCount: sql`${apiUsage.callCount} + 1` })
      .where(eq(apiUsage.id, existing[0].id));
  } else {
    await db.insert(apiUsage).values({
      userId,
      apiKeyId,
      endpoint,
      callCount: 1,
      date: today,
    });
  }
}

export async function getUsageByUserId(userId: number, days: number = 30) {
  const db = await getDb();
  if (!db) return [];

  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  return db.select()
    .from(apiUsage)
    .where(and(
      eq(apiUsage.userId, userId),
      sql`${apiUsage.date} >= ${startDate}`
    ))
    .orderBy(desc(apiUsage.date));
}

/**
 * Get usage breakdown grouped by endpoint for the given user.
 * Returns an array of { tool, calls, percentage } sorted by calls desc.
 */
export async function getUsageBreakdownByEndpoint(userId: number, days: number = 30) {
  const db = await getDb();
  if (!db) return [];

  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  const rows = await db.select({
    endpoint: apiUsage.endpoint,
    totalCalls: sql<number>`SUM(${apiUsage.callCount})`,
  })
    .from(apiUsage)
    .where(and(
      eq(apiUsage.userId, userId),
      sql`${apiUsage.date} >= ${startDate}`
    ))
    .groupBy(apiUsage.endpoint)
    .orderBy(desc(sql`SUM(${apiUsage.callCount})`));

  const grandTotal = rows.reduce((sum, r) => sum + (r.totalCalls || 0), 0) || 1;

  return rows.map(r => ({
    tool: formatEndpointName(r.endpoint),
    calls: r.totalCalls || 0,
    percentage: Math.round(((r.totalCalls || 0) / grandTotal) * 100),
  }));
}

/** Convert endpoint slugs like "content_review" to "Content Review" */
function formatEndpointName(endpoint: string): string {
  return endpoint
    .replace(/[_-]/g, ' ')
    .replace(/\b\w/g, c => c.toUpperCase());
}

export async function getTotalUsageThisMonth(userId: number) {
  const db = await getDb();
  if (!db) return 0;

  const startOfMonth = new Date();
  startOfMonth.setDate(1);
  startOfMonth.setHours(0, 0, 0, 0);

  const result = await db.select({
    total: sql<number>`SUM(${apiUsage.callCount})`
  })
    .from(apiUsage)
    .where(and(
      eq(apiUsage.userId, userId),
      sql`${apiUsage.date} >= ${startOfMonth}`
    ));

  return result[0]?.total || 0;
}

// ============ Billing Functions ============

export async function addBillingRecord(data: InsertBillingHistory) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");

  await db.insert(billingHistory).values(data);
}

export async function getBillingHistory(userId: number, limit: number = 10) {
  const db = await getDb();
  if (!db) return [];

  return db.select()
    .from(billingHistory)
    .where(eq(billingHistory.userId, userId))
    .orderBy(desc(billingHistory.createdAt))
    .limit(limit);
