// ============ Plan Limits ============

export const planLimits: Record<string, { calls: number; rate: number }> = {
  free: { calls: 2000, rate: 10 },
  builder: { calls: 25000, rate: 60 },
  startup: { calls: 150000, rate: 300 },
  scale: { calls: 500000, rate: 1000 },
  business: { calls: 2000000, rate: 5000 },
  enterprise: { calls: Infinity, rate: 10000 },
  enterprise_plus: { calls: Infinity, rate: 50000 },
};

export function getPlanLimit(plan: string) {
  return planLimits[plan] || planLimits.free;
}

// ============ Rate Limiting Functions (Database-backed) ============

export async function checkRateLimit(userId: number, plan: string): Promise<{
  allowed: boolean;
  remaining: number;
  resetAt: number;
  limit: number;
}> {
  const db = await getDb();
  const limits = getPlanLimit(plan);
  const now = Date.now();
  const windowMs = 60 * 1000; // 1 minute window
  const windowKey = `${userId}-${Math.floor(now / windowMs)}`;

  if (!db) {
    // Fallback: allow request if DB unavailable (fail open for availability)
    dbLog.warn({}, '[RateLimit] Database unavailable, allowing request');
    return { allowed: true, remaining: limits.rate, resetAt: now + windowMs, limit: limits.rate };
  }

  try {
    // Check for existing window
    const existing = await db.select()
      .from(rateLimits)
      .where(and(
        eq(rateLimits.userId, userId),
        eq(rateLimits.windowKey, windowKey)
      ))
      .limit(1);

    if (existing.length > 0) {
      const record = existing[0];

      if (record.requestCount >= limits.rate) {
        return {
          allowed: false,
          remaining: 0,
          resetAt: record.windowEnd,
          limit: limits.rate
        };
      }

      // Increment count
      await db.update(rateLimits)
        .set({ requestCount: sql`${rateLimits.requestCount} + 1` })
        .where(eq(rateLimits.id, record.id));

      return {
        allowed: true,
        remaining: limits.rate - record.requestCount - 1,
        resetAt: record.windowEnd,
        limit: limits.rate
      };
    }

    // Create new window
    const windowEnd = now + windowMs;
    await db.insert(rateLimits).values({
      userId,
      windowKey,
      requestCount: 1,
      windowStart: now,
      windowEnd,
    });

    return {
      allowed: true,
      remaining: limits.rate - 1,
      resetAt: windowEnd,
      limit: limits.rate
    };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[RateLimit] Error checking rate limit');
    // Fail open for availability
    return { allowed: true, remaining: limits.rate, resetAt: now + windowMs, limit: limits.rate };
  }
}

export async function cleanupOldRateLimits(): Promise<number> {
  const db = await getDb();
  if (!db) return 0;

  const cutoff = Date.now() - (60 * 60 * 1000); // 1 hour ago

  try {
    const result = await db.delete(rateLimits)
      .where(sql`${rateLimits.windowEnd} < ${cutoff}`);
    return 0; // Drizzle doesn't return affected rows easily
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[RateLimit] Error cleaning up old records');
    return 0;
  }
}

// ============ Emotional History Functions ============

export async function recordEmotionalHistory(data: InsertEmotionalHistory): Promise<number | null> {
  const db = await getDb();
  if (!db) return null;

  try {
    const [row] = await db.insert(emotionalHistory).values(data).returning({ id: emotionalHistory.id });
    return row?.id ?? null;
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[EmotionalHistory] Error recording');
    return null;
  }
}

export async function getEmotionalHistoryByUser(
  userId: number, 
  externalUserId?: string,
  limit: number = 50
): Promise<EmotionalHistory[]> {
  const db = await getDb();
  if (!db) return [];

  try {
