/**
 * Alert Analytics & Incident Grouping Engine
 * 
 * Provides:
 * 1. Time-series analytics — alert frequency by type over 7/30 day windows
 * 2. Summary statistics — total alerts, most frequent type, peak hour, avg acknowledgment time
 * 3. Incident grouping — deduplicates same-type alerts within a time window into incidents
 * 4. Incident lifecycle — open → acknowledged → resolved with notes
 */

import { createLogger } from '../_core/logger';
import { getDb, DatabaseUnavailableError } from '../db';
import { geometryAlertHistory, alertIncidents } from '../../drizzle/schema';
import { eq, and, gte, lte, desc, sql, count, avg, inArray } from 'drizzle-orm';

const log = createLogger('alert-analytics');

/** Drizzle handle, with the `null` that `getDb()` returns when no database is configured removed. */
type AnalyticsDb = NonNullable<Awaited<ReturnType<typeof getDb>>>;

/**
 * Resolve the database handle, or throw if none is configured.
 *
 * `getDb()` returns `null` when DATABASE_URL is absent. Every caller below already
 * runs inside a try/catch that logs and returns a safe empty result, so throwing
 * here routes "no database" into that same degraded path instead of a null deref.
 */
async function requireDb(): Promise<AnalyticsDb> {
  const db = await getDb();
  if (!db) {
    throw new DatabaseUnavailableError('Database unavailable: alert analytics requires a database connection');
  }
  return db;
}

// ─── Types ────────────────────────────────────────────────────────

export interface AlertFrequencyPoint {
  date: string;       // YYYY-MM-DD
  alertType: string;

